// The registry shared by /contributors and /people. Hand-written records
// here; images and commit counts are generated by scripts/people-assets.ts
// into assets.json and contributions.json and merged in below.

export const CONTRIBUTORS_PATH = "/contributors";

type AssetFile = {
    people: Record<string, ImageAsset>;
    orgs: Record<string, ImageAsset>;
};
type ContributionFile = {
    asOf: string;
    people: Record<string, Contribution>;
};

