export const ORGS: Org[] = ORG_RECORDS.map((o) => {
    const logo = ASSETS.orgs[o.id];
    return logo ? { ...o, logo } : o;
});

export const PEOPLE: Person[] = PEOPLE_RECORDS.map((p) => {
    const headshot = ASSETS.people[p.id];
    return headshot ? { ...p, headshot } : p;
});

const orgById = new Map(ORGS.map((o) => [o.id, o]));

export function orgOf(person: Person): Org {
    const org = orgById.get(person.affiliation.orgId);
    if (!org)
        throw new Error(`Unknown org ${person.affiliation.orgId} for ${person.id}`);
    return org;
}

export function peopleIn(list: PersonList): Person[] {
    return PEOPLE.filter((p) => p.lists.includes(list));
}

export function contributionOf(person: Person): Contribution | undefined {
    return GIT.people[person.id];
}

// The GitHub login from a person's github link, if they have one.
export function githubLogin(person: Person): string | undefined {
    const url = person.links.find((l) => l.kind === "github")?.url;
    return url ? /github\.com\/([^/?#]+)/.exec(url)?.[1] : undefined;
}

// "71 commits, 60 merged PRs since Sep 2026", or undefined without history.
export function contributionStats(person: Person): string | undefined {
    const c = contributionOf(person);
    if (!c || c.commits === 0) return undefined;
    const since = new Date(`${c.first}T00:00:00Z`).toLocaleString("en-US", {
        month: "short",
        year: "numeric",
        timeZone: "UTC",
    });
    const commits = `${c.commits} commit${c.commits === 1 ? "" : "s"}`;
    const prs = c.pullRequests
        ? `, ${c.pullRequests} merged PR${c.pullRequests === 1 ? "" : "s"}`
        : "";
    return `${commits}${prs} since ${since}`;
}

export function initials(name: string): string {
    return name
        .split(/\s+/)
        .filter(Boolean)
        .map((w) => w[0]?.toUpperCase() ?? "")
        .slice(0, 2)
        .join("");
}
